BEGIN;
SELECT plan(34);
INSERT INTO auth.users(id,email,encrypted_password,raw_app_meta_data)
VALUES('91000000-0000-4000-8000-000000000001','password-091@example.test','synthetic-initial','{"_invite_provisioned":true}');
CREATE TEMP TABLE password_company AS SELECT (public.provision_company_atomic('91000000-0000-4000-8000-000000000001',
  '{"name":"Password tests","slug":"password-091","domain":"password-091.test"}')->>'id')::uuid id;
GRANT SELECT ON password_company TO authenticated;
SELECT is((SELECT credential_revision FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),0::bigint,'initial credential observation is zero');
UPDATE public.users SET must_change_password=true WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT password_requirement_version FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),1::bigint,'explicit requirement gets a generation');
UPDATE auth.users SET raw_user_meta_data='{"must_change_password":false}' WHERE id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT credential_revision FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),0::bigint,'metadata does not observe a password change');
SELECT ok((SELECT must_change_password FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),'metadata cannot complete required change');
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',1,1)$$,'P0001',NULL,'completion needs a real credential transition');
UPDATE auth.users SET encrypted_password='synthetic-change-1' WHERE id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT credential_revision FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),1::bigint,'real credential transition advances observation');
SELECT ok((SELECT must_change_password FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),'administrative Auth reset preserves requirement');
SELECT ok((SELECT password_changed_at IS NOT NULL FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),'real Auth transition records timestamp');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE tenant_id=(SELECT id FROM password_company) AND action='auth_password_changed'),1,'credential observation has one audit');
SELECT ok((SELECT actor_id IS NULL AND new_values::text NOT LIKE '%synthetic-change%' FROM public.audit_log WHERE tenant_id=(SELECT id FROM password_company) AND action='auth_password_changed'),'system observation does not claim a human actor or copy credential material');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT is(public.has_required_assurance(),false,'required change blocks business assurance even at AAL2');
SELECT is(public.get_my_tenant_id(),NULL::uuid,'required change blocks tenant business scope');
SELECT is(public.user_has_permission('expenses','create'),false,'required change blocks business permission');
SELECT is((SELECT count(*)::int FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),1,'own profile remains readable for password and MFA bootstrap');
SELECT lives_ok($test$DO $body$BEGIN
  BEGIN UPDATE public.users SET must_change_password=false WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
  EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  IF EXISTS(SELECT 1 FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001' AND NOT must_change_password)
    THEN RAISE EXCEPTION 'browser cleared required-password flag';END IF;
END;$body$;$test$,'browser cannot clear requirement directly, whether denied by grants or RLS');
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',1,1)$$,'42501',NULL,'browser cannot call trusted completion');
SELECT ok(NOT has_function_privilege('authenticated','public.observe_auth_password_change()','execute') AND NOT has_function_privilege('anon','public.observe_auth_password_change()','execute'),'credential observer is not a public callable endpoint');
RESET ROLE;
SELECT set_config('request.jwt.claims','{}',true);
SELECT is((public.complete_user_password_change('91000000-0000-4000-8000-000000000001',1,1)->>'completed')::boolean,true,'trusted completion confirms observed credential');
SELECT is((SELECT must_change_password FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),false,'trusted completion clears requirement');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE tenant_id=(SELECT id FROM password_company) AND action='required_password_change_completed'),1,'completion has one audit');
SELECT is((public.complete_user_password_change('91000000-0000-4000-8000-000000000001',1,1)->>'completed')::boolean,true,'same completion can be acknowledged again');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE tenant_id=(SELECT id FROM password_company) AND action='required_password_change_completed'),1,'acknowledgment does not duplicate audit');
UPDATE public.users SET must_change_password=true WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT password_requirement_version FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),2::bigint,'new requirement invalidates earlier completion');
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',1,2)$$,'P0001','AUTH_PASSWORD_CONCURRENT: credential predates the current requirement','earlier password cannot satisfy a newer requirement');
UPDATE auth.users SET encrypted_password='synthetic-change-2' WHERE id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT credential_requirement_version FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),2::bigint,'observation captures the actual requirement generation');
UPDATE public.users SET must_change_password=true WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT is((SELECT password_requirement_version FROM public.users WHERE auth_user_id='91000000-0000-4000-8000-000000000001'),3::bigint,'explicit true-to-true force invalidates in-flight completion');
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',2,2)$$,'P0001',NULL,'stale requirement snapshot cannot complete');
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',2,3)$$,'P0001','AUTH_PASSWORD_CONCURRENT: credential predates the current requirement','current generation cannot reuse an older credential');
UPDATE auth.users SET encrypted_password='synthetic-change-3' WHERE id='91000000-0000-4000-8000-000000000001';
UPDATE public.users SET status='inactive' WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',3,3)$$,'P0001',NULL,'inactive profile cannot complete');
UPDATE public.users SET status='active',locked_until=now()+interval '1 hour' WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000001',3,3)$$,'P0001',NULL,'locked profile cannot complete');
UPDATE public.users SET locked_until=NULL WHERE auth_user_id='91000000-0000-4000-8000-000000000001';
SELECT is((public.complete_user_password_change('91000000-0000-4000-8000-000000000001',3,3)->>'completed')::boolean,true,'active unlocked current credential can complete');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"91000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT is(public.get_my_tenant_id(),(SELECT id FROM password_company),'business scope returns after completed password and MFA');
RESET ROLE;
SELECT set_config('request.jwt.claims','{}',true);
SELECT throws_ok($$SELECT public.complete_user_password_change('91000000-0000-4000-8000-000000000099',3,3)$$,'P0001',NULL,'unknown account cannot complete');
SELECT throws_ok($$UPDATE public.users SET credential_revision=-1 WHERE auth_user_id='91000000-0000-4000-8000-000000000001'$$,'23514',NULL,'credential revisions cannot be negative');
SELECT * FROM finish();
ROLLBACK;
